mapper.update:
/* apiSimpleView.updSpcEssential */
UPDATE KOA_TB_API_SPC
SET
   API_NM   = #{apiNm}
  ,API_DESC = #{apiDesc}
  ,HOST     = #{host}
  ,BAS_PATH = #{basPath}
  ,AMD_DT   = NOW()
  ,AMDR     = #{amdr}
WHERE API_SPC_NO = #{apiSpcNo}::integer

/* apiSimpleView.updDefDetail */
UPDATE KOA_TB_API_DEF
SET
   ENDPNT_TB_URL            = #{endpntTbUrl}
  ,ENDPNT_PRD_URL           = #{endpntPrdUrl}
  ,ENDPNT_CLIENT_IP         = #{endpntClientIp}
  ,ENDPNT_TIMEOUT           = NULLIF(#{endpntTimeout}, '')::integer
  ,RESMAP_RES_CD_FIELD      = #{resmapResCdField}
  ,RESMAP_SUCC_VAL          = #{resmapSuccVal}
  ,RESMAP_ERR_CD_FIELD      = #{resmapErrCdField}
  ,RESMAP_ERR_MSG_FIELD     = #{resmapErrMsgField}
  ,HDP_API_OUT_FORMAT       = #{hdpApiOutFormat}
  ,HDP_API_OUT_COMMON_PARAM = #{hdpApiOutCommonParam}
  ,HDP_API_ENDPOINT_ID      = #{hdpApiEndpointId}
  ,HDP_REQ_API_NAME         = #{hdpReqApiName}
  ,HDP_REQ_MAPPING_TO_BODY  = #{hdpReqMappingToBody}
  ,HDP_RES_MAPPING_TO_BODY  = #{hdpResMappingToBody}
  ,AMD_DT                   = NOW()
  ,AMDR                     = #{amdr}
WHERE API_NO = #{apiNo}::integer

mapper.insert:
/* apiSimpleView.savParam */

  SELECT CURRVAL('koa_tb_api_param_param_no_seq')

INSERT INTO KOA_TB_API_PARAM
(
   API_NO
  ,PARAM_TYPE_CD
  ,SORT_ODRG
  ,PARAM_NM
  ,DATA_TYPE_CD
  ,PARAM_DESC
  ,PARAM_LOC
  ,REQUIRED
  ,PRNTS_PARAM_NO
  ,OBJ_NO
  ,OBJ_ODRG
  ,EXAM
  ,PERSONAL_DATA
  ,REG_DT
  ,REGR
  ,AMD_DT
  ,AMDR
)
VALUES
(
   #{apiNo}::integer
  ,#{paramTypeCd}
  ,#{sortOdrg}::integer
  ,#{paramNm}
  ,#{dataTypeCd}
  ,#{paramDesc}
  ,#{paramLoc}
  ,#{required}
  ,NULLIF(#{prntsParamNo}, '')::integer
  ,NULLIF(#{objNo}, '')::integer
  ,NULLIF(#{objOdrg}, '')::integer
  ,#{exam}
  ,#{personalData}
  ,NOW()
  ,#{regr}
  ,NOW()
  ,#{regr}
)
